"1849 :   private List<Node> getRhsSubexpressions(Node n) {
1850 :     switch (n.getType()) {
1851 :       case Token.EXPR_RESULT:
1852 :         // process body
1853 :         return getRhsSubexpressions(n.getFirstChild());
1854 :       case Token.FUNCTION:
1855 :         // function nodes have no RHS
1856 :         return Collections.emptyList();
1857 :       case Token.NAME:
1858 :         {
1859 :           // parent is a var node.  RHS is the first child
1860 :           Node rhs = n.getFirstChild();
1861 :           if (rhs != null) {
1862 :             return Lists.newArrayList(rhs);
1863 :           } else {
1864 :             return Collections.emptyList();
1865 :           }
1866 :         }
1867 :       case Token.ASSIGN:
1868 :         {
1869 :           // add LHS and RHS expressions - LHS may be a complex expression
1870 :           Node lhs = n.getFirstChild();
1871 :           Node rhs = lhs.getNext();
1872 :           return Lists.newArrayList(lhs, rhs);
1873 :         }
1874 :       case Token.VAR:
1875 :         {
1876 :           // recurse on all children
1877 :           List<Node> nodes = Lists.newArrayList();
1878 :           for (Node child : n.children()) {
1879 :             nodes.addAll(getRhsSubexpressions(child));
1880 :           }
1881 :           return nodes;
1882 :         }
1883 :       default:
1884 :         throw new IllegalArgumentException("AstChangeProxy::getRhs " + n);
1885 :     }
1886 :   }"

"1799 :   private boolean valueConsumedByParent(Node n, Node parent) {
1800 :     if (NodeUtil.isAssignmentOp(parent)) {
1801 :       return parent.getLastChild() == n;
1802 :     }
1803 : 
1804 :     switch (parent.getType()) {
1805 :       case Token.NAME:
1806 :       case Token.RETURN:
1807 :         return true;
1808 :       case Token.AND:
1809 :       case Token.OR:
1810 :       case Token.HOOK:
1811 :         return parent.getFirstChild() == n;
1812 :       case Token.FOR:
1813 :         return parent.getFirstChild().getNext() == n;
1814 :       case Token.IF:
1815 :       case Token.WHILE:
1816 :         return parent.getFirstChild() == n;
1817 :       case Token.DO:
1818 :         return parent.getLastChild() == n;
1819 :       default:
1820 :         return false;
1821 :     }
1822 :   }"

"1401 :   private NameInformation createNameInformation(NodeTraversal t, Node n) {
1402 :     Node parent = n.getParent();
1403 :     // Build the full name and find its root node by iterating down through all
1404 :     // GETPROP/GETELEM nodes.
1405 :     String name = "";
1406 :     Node rootNameNode = n;
1407 :     boolean bNameWasShortened = false;
1408 :     while (true) {
1409 :       if (NodeUtil.isGet(rootNameNode)) {
1410 :         Node prop = rootNameNode.getLastChild();
1411 :         if (rootNameNode.isGetProp()) {
1412 :           name = "." + prop.getString() + name;
1413 :         } else {
1414 :           // We consider the name to be "a.b" in a.b['c'] or a.b[x].d.
1415 :           bNameWasShortened = true;
1416 :           name = "";
1417 :         }
1418 :         rootNameNode = rootNameNode.getFirstChild();
1419 :       } else if (NodeUtil.isObjectLitKey(rootNameNode)) {
1420 :         name = "." + rootNameNode.getString() + name;
1421 : 
1422 :         // Check if this is an object literal assigned to something.
1423 :         Node objLit = rootNameNode.getParent();
1424 :         Node objLitParent = objLit.getParent();
1425 :         if (objLitParent.isAssign()) {
1426 :           // This must be the right side of the assign.
1427 :           rootNameNode = objLitParent.getFirstChild();
1428 :         } else if (objLitParent.isName()) {
1429 :           // This must be a VAR initialization.
1430 :           rootNameNode = objLitParent;
1431 :         } else if (objLitParent.isStringKey()) {
1432 :           // This must be a object literal key initialization.
1433 :           rootNameNode = objLitParent;
1434 :         } else {
1435 :           return null;
1436 :         }
1437 :       } else {
1438 :         break;
1439 :       }
1440 :     }
1441 : 
1442 :     // Check whether this is a class-defining call. Classes may only be defined
1443 :     // in the global scope.
1444 :     if (parent.isCall() && t.inGlobalScope()) {
1445 :       CodingConvention convention = compiler.getCodingConvention();
1446 :       SubclassRelationship classes = convention.getClassesDefinedByCall(parent);
1447 :       if (classes != null) {
1448 :         NameInformation nameInfo = new NameInformation();
1449 :         nameInfo.name = classes.subclassName;
1450 :         nameInfo.onlyAffectsClassDef = true;
1451 :         nameInfo.superclass = classes.superclassName;
1452 :         return nameInfo;
1453 :       }
1454 : 
1455 :       String singletonGetterClass =
1456 :           convention.getSingletonGetterClassName(parent);
1457 :       if (singletonGetterClass != null) {
1458 :         NameInformation nameInfo = new NameInformation();
1459 :         nameInfo.name = singletonGetterClass;
1460 :         nameInfo.onlyAffectsClassDef = true;
1461 :         return nameInfo;
1462 :       }
1463 :     }
1464 : 
1465 :     switch (rootNameNode.getType()) {
1466 :       case Token.NAME:
1467 :         // Check whether this is an assignment to a prototype property
1468 :         // of an object defined in the global scope.
1469 :         if (!bNameWasShortened &&
1470 :             n.isGetProp() &&
1471 :             parent.isAssign() &&
1472 :             "prototype".equals(n.getLastChild().getString())) {
1473 :           if (createNameInformation(t, n.getFirstChild()) != null) {
1474 :             name = rootNameNode.getString() + name;
1475 :             name = name.substring(0, name.length() - PROTOTYPE_SUFFIX_LEN);
1476 :             NameInformation nameInfo = new NameInformation();
1477 :             nameInfo.name = name;
1478 :             return nameInfo;
1479 :           } else {
1480 :             return null;
1481 :           }
1482 :         }
1483 :         return createNameInformation(
1484 :             rootNameNode.getString() + name, t.getScope(), rootNameNode);
1485 :       case Token.THIS:
1486 :         if (t.inGlobalScope()) {
1487 :           NameInformation nameInfo = new NameInformation();
1488 :           if (name.indexOf('.') == 0) {
1489 :             nameInfo.name = name.substring(1);  // strip leading "."
1490 :           } else {
1491 :             nameInfo.name = name;
1492 :           }
1493 :           nameInfo.isExternallyReferenceable = true;
1494 :           return nameInfo;
1495 :         }
1496 :         return null;
1497 :       default:
1498 :         return null;
1499 :     }
1500 :   }"

"908 :     private void maybeRecordReferenceOrAlias(
909 :         NodeTraversal t, Node n, Node parent,
910 :         NameInformation nameInfo, NameInformation referring) {
911 :       String referringName = "";
912 :       if (referring != null) {
913 :         referringName = referring.isPrototype
914 :                       ? referring.prototypeClass
915 :                       : referring.name;
916 :       }
917 : 
918 :       String name = nameInfo.name;
919 : 
920 :       // A value whose result is the return value of a function call
921 :       // can be an alias to global object.
922 :       // Here we add an alias to the general "global" object
923 :       // to act as a placeholder for the actual (unnamed) value.
924 :       if (maybeHiddenAlias(n)) {
925 :         recordAlias(name, WINDOW);
926 :       }
927 : 
928 :       // An externally referenceable name must always be defined, so we add a
929 :       // reference to it from the global scope (a.k.a. window).
930 :       if (nameInfo.isExternallyReferenceable) {
931 :         recordReference(WINDOW, name, RefType.REGULAR);
932 :         maybeRecordAlias(name, parent, referring, referringName);
933 :         return;
934 :       }
935 : 
936 :       // An assignment implies a reference from the enclosing dependency scope.
937 :       // For example, foo references bar in: function foo() {bar=5}.
938 :       if (NodeUtil.isVarOrSimpleAssignLhs(n, parent)) {
939 :         if (referring != null) {
940 :           recordReference(referringName, name, RefType.REGULAR);
941 :         }
942 :         return;
943 :       }
944 : 
945 :       if (nodesToKeep.contains(n)) {
946 :         List<NameInformation> functionScopes =
947 :             getEnclosingFunctionDependencyScope(t);
948 :         if (!functionScopes.isEmpty()) {
949 :           for (NameInformation functionScope : functionScopes) {
950 :             recordReference(functionScope.name, name, RefType.REGULAR);
951 :           }
952 :         } else {
953 :           recordReference(WINDOW, name, RefType.REGULAR);
954 :           if (referring != null) {
955 :             maybeRecordAlias(name, parent, referring, referringName);
956 :           }
957 :         }
958 :       } else if (referring != null) {
959 :         if (!maybeRecordAlias(name, parent, referring, referringName)) {
960 :           RefType depType = referring.onlyAffectsClassDef ?
961 :               RefType.INHERITANCE : RefType.REGULAR;
962 :           recordReference(referringName, name, depType);
963 :         }
964 :       } else {
965 :         // No named dependency scope found.  Unfortunately that might
966 :         // mean that the expression is a child of an function expression
967 :         // or assignment with a complex lhs.  In those cases,
968 :         // protect this node by creating a reference to WINDOW.
969 :         for (Node ancestor : n.getAncestors()) {
970 :           if (NodeUtil.isAssignmentOp(ancestor) ||
971 :               ancestor.isFunction()) {
972 :             recordReference(WINDOW, name, RefType.REGULAR);
973 :             break;
974 :           }
975 :         }
976 :       }
977 :     }"

